head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vPreDate = "";

// 세션정보를 얻기위한 함수사용
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        if (js_market === "1" || js_market === "2") {
            $c.cm.setColumnProp(grd_List_1, "TR_MKT_NM", "Show", false);
            $c.cm.setColumnProp(grd_List_1, "ITEM_NM", "Width", $c.cm.getColumnProp(grd_List_1, "TR_MKT_NM", "Width") + $c.cm.getColumnProp(grd_List_1, "ITEM_NM", "Width"));
            if (js_market === "2") {
                MaxTab_01.setDisabled(true);
            } else {
                MaxTab_01.setDisabled(false);
            }
        }
        if (js_dep_cd === '2540') {
            // 심사2팀
            MaxTab_01.setSelectedTabIndex(2);
        } else {
            MaxTab_01.setSelectedTabIndex(1);
        }

        //    PanelToGroupBox_01(panel_1);
        //    PanelToGroupBox_01(panel_5);
        await scwin.setInit();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "topListingNotice.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        let today = $c.ut.cGetToday("yyyymmddhhmmss");
        // 파일형식 today_화면명.xls
        let xls_path = $c.session.getExcelDownPath() + today + "_ELW공지사항.xls";
        $c.data.downloadGridViewOffice(grd_ELW_List_1, "익일최종거래일에의한 상장폐지종목", xls_path, 4, 0);
        $c.data.downloadGridViewOffice(grd_ELW_List_2, "금일행사종료일1개월전 상장폐지예고종목", xls_path, 36, 0);
        $c.data.downloadGridViewOffice(grd_ELW_List_3, "금일전부보유1개월로 인한 상장폐지 우려종목", xls_path, 36, 0);
        $c.data.downloadGridViewOffice(grd_ELW_List_4, "기초자산미등록회사", xls_path, 32, 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "topListingNotice.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "topListingNotice.btn_Close_onclick" });
    }
};

